         PurchaseHistory = r.PurchaseHistory,
         Label = string.Equals(r.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
     })
     .ToList();
 var dataView = mlContext.Data.LoadFromEnumerable(mappedData);

 var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);

